package com.davidblackcn.buildupmobtweaks;
import com.davidblackcn.buildupmobtweaks.villager.profession.*;
import net.fabricmc.api.ModInitializer;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.gametest.framework.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.*;
import net.minecraft.resources.ResourceKey;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.npc.villager.*;
import net.minecraft.world.entity.decoration.*;
import net.minecraft.world.entity.projectile.arrow.*;
import net.minecraft.world.entity.ai.memory.*;
import net.minecraft.world.entity.schedule.Activity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.nbt.CompoundTag;
import com.mojang.serialization.MapCodec;
import java.util.*;
import static com.davidblackcn.buildupmobtweaks.FarmerIntelligenceTests.*;
import static com.davidblackcn.buildupmobtweaks.ProfessionResourceTests.ops;
public final class ProfessionRefinementTests implements ModInitializer {
    static final String ENV="buildupmobtweaks:profession_refinement";
    public record Settings(ProfessionCoreTests.Settings core,boolean daily,boolean frame,boolean stand,boolean block,boolean archery,boolean wool){}
    public record Environment() implements TestEnvironmentDefinition<Settings>{
        static final MapCodec<Environment> CODEC=MapCodec.unit(Environment::new);
        public Settings setup(ServerLevel l){var old=new ProfessionCoreTests.Environment().setup(l);var c=BuildupMobTweaks.config().villagers.professions;var out=new Settings(old,c.daily_routines.get(),c.decoration_frames.get(),c.decoration_stands.get(),c.decoration_blocks.get(),c.archery_training.get(),c.wool_pickup.get());c.daily_routines.accept(false);c.decoration_frames.accept(true);c.decoration_stands.accept(true);c.decoration_blocks.accept(true);c.archery_training.accept(true);c.wool_pickup.accept(true);c.action_cooldown.accept(2400);return out;}
        public void teardown(ServerLevel l,Settings o){var c=BuildupMobTweaks.config().villagers.professions;c.daily_routines.accept(o.daily());c.decoration_frames.accept(o.frame());c.decoration_stands.accept(o.stand());c.decoration_blocks.accept(o.block());c.archery_training.accept(o.archery());c.wool_pickup.accept(o.wool());new ProfessionCoreTests.Environment().teardown(l,o.core());}
        public MapCodec<Environment> codec(){return CODEC;}
    }
    public void onInitialize(){Registry.register(BuiltInRegistries.TEST_ENVIRONMENT_DEFINITION_TYPE,BuildupMobTweaks.id("profession_refinement_test"),Environment.CODEC);}
    static Villager display(GameTestHelper h,String kind){var v=ProfessionResourceTests.worker(h,kind.equals("frame")?VillagerProfession.LIBRARIAN:kind.equals("stand")?VillagerProfession.ARMORER:VillagerProfession.MASON,kind.equals("frame")?Blocks.LECTERN:kind.equals("stand")?Blocks.BLAST_FURNACE:Blocks.STONECUTTER);v.getInventory().setItem(0,new ItemStack(kind.equals("frame")?Items.ITEM_FRAME:kind.equals("stand")?Items.ARMOR_STAND:Items.DECORATED_POT));if(!kind.equals("block"))v.getInventory().setItem(1,new ItemStack(kind.equals("frame")?Items.BOOK:Items.IRON_HELMET));if(kind.equals("frame"))h.setBlock(new BlockPos(6,2,8),Blocks.STONE);return v;}
    static CompoundTag receipt(Villager v,String kind){return v.getAttached(OwnedWorkDisplays.LEDGER).getCompound("instances").orElseThrow().getCompound(kind).orElseThrow();}
    static Entity entity(GameTestHelper h,CompoundTag d){return h.getLevel().getEntity(UUID.fromString(d.getStringOr("uuid","")));}
    static void finish(GameTestHelper h,Villager v,String scene){BuildupMobTweaks.LOGGER.info("A3_REFINEMENT_PROOF scene={} ops={} inventory={} ledger={}",scene,ops(v),v.getInventory().getItems(),v.getAttached(OwnedWorkDisplays.LEDGER));v.discard();h.succeed();}
    static void refund(GameTestHelper h,String kind){var v=display(h,kind);CompoundTag[] d={null};h.onEachTick(()->{if(d[0]==null&&ops(v)==1){d[0]=receipt(v,kind).copy();v.addTag("buildupmobtweaks:profession_external");}});h.runAtTickTime(850,()->{h.assertTrue(d[0]!=null&&v.getAttached(OwnedWorkDisplays.LEDGER).getCompound("instances").orElseThrow().isEmpty(),"Known display is retired exactly once");if(kind.equals("block"))h.assertTrue(h.getLevel().getBlockState(BlockPos.of(d[0].getLongOr("pos",0))).isAir()&&v.getInventory().countItem(Items.DECORATED_POT)==1,"Paid pot returns once");else h.assertTrue(entity(h,d[0])==null&&v.getInventory().countItem(kind.equals("frame")?Items.ITEM_FRAME:Items.ARMOR_STAND)==1&&v.getInventory().countItem(kind.equals("frame")?Items.BOOK:Items.IRON_HELMET)==1,"Actual equipment and paid base return once without loot");finish(h,v,"refund_"+kind);});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=950) public void paidFrameReturnsOnlyOriginalMaterialsOnExternalYield(GameTestHelper h){refund(h,"frame");}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=950) public void paidStandReturnsOnlyOriginalEquipmentOnExternalYield(GameTestHelper h){refund(h,"stand");}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=950) public void paidPotReturnsOnlyOriginalMaterialOnExternalYield(GameTestHelper h){refund(h,"block");}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=950)
    public void playerModifiedFrameSurvivesWithoutSnapshotRefund(GameTestHelper h){var v=display(h,"frame");Entity[] saved={null};h.onEachTick(()->{if(saved[0]==null&&ops(v)==1){saved[0]=entity(h,receipt(v,"frame"));((ItemFrame)saved[0]).setItem(new ItemStack(Items.DIAMOND),false);v.addTag("buildupmobtweaks:profession_external");}});h.runAtTickTime(850,()->{h.assertTrue(saved[0]!=null&&!saved[0].isRemoved()&&((ItemFrame)saved[0]).getItem().is(Items.DIAMOND)&&!saved[0].hasAttached(OwnedWorkDisplays.MARKER)&&v.getInventory().isEmpty(),"Player changed item survives; obsolete receipt cannot mint book/frame");finish(h,v,"player_frame");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=950)
    public void playerFilledPotSurvivesWithoutRefund(GameTestHelper h){var v=display(h,"block");BlockPos[] pos={null};h.onEachTick(()->{if(pos[0]==null&&ops(v)==1){pos[0]=BlockPos.of(receipt(v,"block").getLongOr("pos",0));((DecoratedPotBlockEntity)h.getLevel().getBlockEntity(pos[0])).setTheItem(new ItemStack(Items.DIAMOND));v.addTag("buildupmobtweaks:profession_external");}});h.runAtTickTime(850,()->{var be=h.getLevel().getBlockEntity(pos[0]);h.assertTrue(be instanceof DecoratedPotBlockEntity pot&&pot.getTheItem().is(Items.DIAMOND)&&!be.hasAttached(OwnedWorkDisplays.MARKER)&&v.getInventory().isEmpty(),"Player content remains and paid pot is relinquished");finish(h,v,"player_pot");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=950)
    public void identicalPlayerReplacementPotIsNeverDeleted(GameTestHelper h){var v=display(h,"block");BlockPos[] pos={null};h.onEachTick(()->{if(pos[0]==null&&ops(v)==1){pos[0]=BlockPos.of(receipt(v,"block").getLongOr("pos",0));h.getLevel().setBlock(pos[0],Blocks.AIR.defaultBlockState(),3);h.getLevel().setBlock(pos[0],Blocks.DECORATED_POT.defaultBlockState(),3);v.addTag("buildupmobtweaks:profession_external");}});h.runAtTickTime(850,()->{h.assertTrue(pos[0]!=null&&h.getLevel().getBlockState(pos[0]).is(Blocks.DECORATED_POT)&&!h.getLevel().getBlockEntity(pos[0]).hasAttached(OwnedWorkDisplays.MARKER)&&v.getInventory().isEmpty(),"Identical replacement has different ownership and is preserved without refund");finish(h,v,"replacement_pot");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=950)
    public void displayReloadRetainsUniqueCarrierAndDebitedInventory(GameTestHelper h){Villager[] v={display(h,"stand")};CompoundTag[] raw={null};UUID[] id={null};h.onEachTick(()->{if(raw[0]==null&&ops(v[0])==1){raw[0]=v[0].getAttached(OwnedWorkDisplays.LEDGER).copy();id[0]=entity(h,receipt(v[0],"stand")).getUUID();v[0]=CombatTestWorld.reload(h,v[0]);}});h.runAtTickTime(850,()->{h.assertTrue(raw[0]!=null&&raw[0].equals(v[0].getAttached(OwnedWorkDisplays.LEDGER))&&h.getLevel().getEntity(id[0]) instanceof ArmorStand&&v[0].getInventory().isEmpty()&&ops(v[0])==0,"Entity serialization preserves exact paid receipt and does not place a duplicate");v[0].addTag("buildupmobtweaks:profession_external");finish(h,v[0],"display_reload");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=700)
    public void futureDisplayLedgerPausesPlacementWithoutChangingRawData(GameTestHelper h){var v=display(h,"frame");var raw=new CompoundTag();raw.putInt("version",99);raw.putString("future","keep");v.setAttached(OwnedWorkDisplays.LEDGER,raw.copy());h.runAtTickTime(600,()->{h.assertTrue(raw.equals(v.getAttached(OwnedWorkDisplays.LEDGER))&&ops(v)==0&&v.getInventory().countItem(Items.ITEM_FRAME)==1&&v.getInventory().countItem(Items.BOOK)==1,"Unknown ledger preserved; no world/resource operations");finish(h,v,"future_display");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=700)
    public void deniedDecorationKeepsRealMaterials(GameTestHelper h){var v=display(h,"stand");v.addTag("test_deny_all");h.runAtTickTime(600,()->{h.assertTrue(ops(v)==0&&v.getInventory().countItem(Items.ARMOR_STAND)==1&&v.getInventory().countItem(Items.IRON_HELMET)==1,"Protection provider denies before any placement/debit");finish(h,v,"denied_display");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=700)
    public void emptyInventoryDoesNotProduceDecorativeArmor(GameTestHelper h){var v=display(h,"stand");v.getInventory().clearContent();h.runAtTickTime(600,()->{h.assertTrue(ops(v)==0&&!v.hasAttached(OwnedWorkDisplays.LEDGER),"No free prop or base carrier");finish(h,v,"no_display_materials");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=950)
    public void trainingArrowReallyHitsTargetAndCannotBePickedUp(GameTestHelper h){var v=ProfessionResourceTests.worker(h,VillagerProfession.FLETCHER,Blocks.FLETCHING_TABLE);v.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.BOW));v.getInventory().setItem(0,new ItemStack(Items.ARROW));h.setBlock(new BlockPos(12,3,8),Blocks.TARGET);boolean[] draw={false},hit={false},real={false};h.onEachTick(()->{draw[0]|=v.isUsingItem();hit[0]|=h.getBlockState(new BlockPos(12,3,8)).getValue(BlockStateProperties.POWER)>0;for(var a:h.getLevel().getEntitiesOfClass(Arrow.class,v.getBoundingBox().inflate(8),e->e.getOwner()==v)){real[0]=true;h.assertTrue(a.pickup==AbstractArrow.Pickup.DISALLOWED,"Real training arrow cannot be picked up");}});h.runAtTickTime(850,()->{h.assertTrue(draw[0]&&real[0]&&hit[0]&&ops(v)==1&&v.getInventory().countItem(Items.ARROW)==0&&v.getMainHandItem().getDamageValue()==1&&!v.isUsingItem(),"Native target signal proves physical hit with one real arrow and bow debit");finish(h,v,"archery");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=950)
    public void tradeInterruptsNativeBowDrawBeforeDebit(GameTestHelper h){var v=ProfessionResourceTests.worker(h,VillagerProfession.FLETCHER,Blocks.FLETCHING_TABLE);v.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.BOW));v.getInventory().setItem(0,new ItemStack(Items.ARROW));h.setBlock(new BlockPos(12,3,8),Blocks.TARGET);v.getOffers();var p=h.makeMockPlayer(net.minecraft.world.level.GameType.SURVIVAL);boolean[] draw={false};h.onEachTick(()->{if(!draw[0]&&v.isUsingItem()){draw[0]=true;v.setTradingPlayer(p);}});h.runAtTickTime(850,()->{h.assertTrue(draw[0]&&ops(v)==0&&!v.isUsingItem()&&v.getInventory().countItem(Items.ARROW)==1&&v.getMainHandItem().getDamageValue()==0,"Trade cancels native bow use with no resource or projectile settlement");v.setTradingPlayer(null);finish(h,v,"archery_trade");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=850)
    public void ownActivityDisableStopsResourceWorkBeforeCommit(GameTestHelper h){var v=ProfessionResourceTests.worker(h,VillagerProfession.SHEPHERD,Blocks.LOOM);v.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.SHEARS));var sheep=ProfessionResourceTests.sheep(h,false);boolean[] cut={false};h.onEachTick(()->{if(!cut[0]&&ProfessionWorkState.busy(v)){cut[0]=true;v.addTag("buildupmobtweaks:disable_work/buildupmobtweaks:shear_sheep");}});h.runAtTickTime(750,()->{h.assertTrue(cut[0]&&!sheep.isSheared()&&ops(v)==0&&!ProfessionWorkState.busy(v),"Per-activity opt-out wins at the tick boundary");finish(h,v,"activity_off");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=850)
    public void removedWorkstationInterruptsBeforeWorldSettlement(GameTestHelper h){var v=ProfessionResourceTests.worker(h,VillagerProfession.SHEPHERD,Blocks.LOOM);v.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.SHEARS));var sheep=ProfessionResourceTests.sheep(h,false);boolean[] cut={false};h.onEachTick(()->{if(!cut[0]&&ProfessionWorkState.busy(v)){cut[0]=true;h.getLevel().setBlock(p(h,8,8),Blocks.AIR.defaultBlockState(),3);h.getLevel().getPoiManager().remove(p(h,8,8));}});h.runAtTickTime(750,()->{h.assertTrue(cut[0]&&!sheep.isSheared()&&ops(v)==0&&!ProfessionWorkState.busy(v),"Native missing POI interrupts before real resources change");finish(h,v,"removed_station");});}

    @GameTest(environment=ENV,structure=ARENA,maxTicks=850)
    public void twoShepherdsCompeteForOneSheepWithoutDuplicateWool(GameTestHelper h){var a=ProfessionResourceTests.worker(h,VillagerProfession.SHEPHERD,Blocks.LOOM);var b=EntityTypes.VILLAGER.create(h.getLevel(),EntitySpawnReason.COMMAND);b.snapTo(a.getX(),a.getY(),a.getZ()+1,0,0);b.setVillagerData(a.getVillagerData());b.setVillagerXp(20);var job=p(h,8,10);h.getLevel().setBlock(job,Blocks.LOOM.defaultBlockState(),3);var poi=net.minecraft.world.entity.ai.village.poi.PoiTypes.forState(h.getLevel().getBlockState(job)).orElseThrow();h.getLevel().getPoiManager().add(job,poi);h.getLevel().getPoiManager().take(x->true,(x,q)->q.equals(job),job,1);b.getBrain().setMemory(MemoryModuleType.JOB_SITE,GlobalPos.of(h.getLevel().dimension(),job));b.refreshBrain(h.getLevel());b.getBrain().setActiveActivityIfPossible(Activity.WORK);b.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MOVEMENT_SPEED).setBaseValue(0);b.setCanPickUpLoot(false);h.getLevel().addFreshEntity(b);for(var v:List.of(a,b))v.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.SHEARS));var sheep=ProfessionResourceTests.sheep(h,false);h.runAtTickTime(750,()->{int wool=a.getInventory().getItems().stream().filter(s->s.is(net.minecraft.tags.ItemTags.WOOL)).mapToInt(ItemStack::getCount).sum()+b.getInventory().getItems().stream().filter(s->s.is(net.minecraft.tags.ItemTags.WOOL)).mapToInt(ItemStack::getCount).sum()+ProfessionResourceTests.wool(h);h.assertTrue(sheep.isSheared()&&ops(a)+ops(b)==1&&a.getMainHandItem().getDamageValue()+b.getMainHandItem().getDamageValue()==1&&wool>=1&&wool<=3,"One actual shear wins temporary claim and one native loot settlement");b.discard();finish(h,a,"two_shepherds");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=850)
    public void optionalWoolCollectionIgnoresExistingPlayerPile(GameTestHelper h){var v=ProfessionResourceTests.worker(h,VillagerProfession.SHEPHERD,Blocks.LOOM);v.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.SHEARS));var sheep=ProfessionResourceTests.sheep(h,false);var pile=new net.minecraft.world.entity.item.ItemEntity(h.getLevel(),sheep.getX(),sheep.getY(),sheep.getZ(),new ItemStack(Items.WOOL.red(),17));pile.setNoGravity(true);pile.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);h.getLevel().addFreshEntity(pile);h.runAtTickTime(750,()->{int got=v.getInventory().getItems().stream().filter(s->s.is(net.minecraft.tags.ItemTags.WOOL)).mapToInt(ItemStack::getCount).sum();h.assertTrue(ops(v)==1&&got>=1&&got<=3&&pile.isAlive()&&pile.getItem().getCount()==17,"Collects only UUIDs emitted by this exact native shear; player pile remains");finish(h,v,"wool_collection");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=850)
    public void replacingBrainInterruptsOldOwnedWorkWithoutTouchingReplacement(GameTestHelper h){var v=display(h,"stand");boolean[] changed={false};h.onEachTick(()->{if(!changed[0]&&ProfessionWorkState.busy(v)){changed[0]=true;v.refreshBrain(h.getLevel());v.addTag("buildupmobtweaks:profession_external");}});h.runAtTickTime(750,()->{h.assertTrue(changed[0]&&ops(v)==0&&!ProfessionWorkState.busy(v)&&v.getInventory().countItem(Items.ARMOR_STAND)==1,"Brain replacement aborts old pending world write; resources stay owned");finish(h,v,"replacement_brain");});}
    @GameTest(environment=ENV,structure=ARENA,maxTicks=850)
    public void nativeRaidActivityInterruptsPendingPlacement(GameTestHelper h){var v=display(h,"stand");boolean[] changed={false};h.onEachTick(()->{if(!changed[0]&&ProfessionWorkState.busy(v)){changed[0]=true;v.getBrain().setActiveActivityIfPossible(Activity.PRE_RAID);}});h.runAtTickTime(750,()->{h.assertTrue(changed[0]&&ops(v)==0&&!ProfessionWorkState.busy(v)&&v.getInventory().countItem(Items.ARMOR_STAND)==1,"Native pre-raid slot aborts uncommitted work");finish(h,v,"raid_yield");});}
}
